            )

            print(
                f"⚡ Local tool: {direct_action}"
            )

            # -------------------------------------------------
            # CLOSE APPLICATION
            #
            # This goes through the normal confirmation
            # system without using Gemini.
            # -------------------------------------------------

            if direct_action == "close_application":

                result = self.execute_direct_tool(
                    direct_action,
                    direct_arguments,
                )

                if not result.get(
                    "success",
                    False,
                ):

                    return (
                        "I could not complete "
                        "the request: "
                        f"{result.get('error', 'Unknown error.')}"
                    )

                # ---------------------------------------------
                # CHECK CONFIRMATION
                # ---------------------------------------------

                tool_result_data = result.get(
                    "result",
                    {},
                )

                if not isinstance(
                    tool_result_data,
                    dict,
                ):
                    tool_result_data = {}

                confirmation_required = (
                    result.get(
                        "requires_confirmation",
                        False,
                    )
                    or
                    result.get(
                        "confirmation_required",
                        False,
                    )
                    or
                    tool_result_data.get(
                        "requires_confirmation",
                        False,
                    )
                    or
                    tool_result_data.get(
                        "confirmation_required",
                        False,
                    )
                )

                if confirmation_required:

                    confirmation_message = (
                        result.get(
                            "message",
                            tool_result_data.get(
                                "message",
                                "This action requires confirmation.",
                            ),
                        )
                    )

                    pending_action = (
                        "force_close_application"
                    )

                    pending_arguments = {
                        "app_name":
                            direct_arguments.get(
                                "app_name",
                                "",
                            )
                    }

                    self.confirmation_manager.set_pending(
                        action=pending_action,
                        arguments=pending_arguments,
                        message=confirmation_message,
                        original_request=user_input,
                    )

                    print(
                        "🔐 Confirmation required."
                    )

                    return (
                        "This action requires confirmation."
                    )

                return self.build_local_direct_response(
                    user_input,
                    direct_action,
                    result,
                )

            # -------------------------------------------------
            # NORMAL LOCAL TOOL
            # -------------------------------------------------

            result = self.execute_direct_tool(
                direct_action,
                direct_arguments,
            )

            if not result.get(
                "success",
                False,
            ):

                return (
                    "I could not complete "
                    "the request: "
                    f"{result.get('error', 'Unknown error.')}"
                )

            return self.build_local_direct_response(
                user_input,
                direct_action,
                result,
            )
        # =====================================================
        # OBVIOUS CONVERSATION
        # =====================================================

        if self.is_obvious_conversation(
            user_input
        ):

            return self.brain.process(
                user_input
            )

        # =====================================================
        # CREATE PLAN
        # =====================================================

        planner_context = (
            self.build_planner_context()
        )

        plan = self.planner.create_plan(
            user_input,
            context=planner_context,
        )

        if not plan:

            return (
                "I could not create a "
                "plan for that request."
            )

        # =====================================================
        # CONVERSATION ONLY
        # =====================================================

        if (
            len(plan) == 1
            and plan[0].get(
                "action"
            ) == "conversation"
        ):

            response = self.brain.process(
                user_input
            )

            self.conversation_context.append(
                {
                    "user": user_input,
                    "tool_results": [],
                    "assistant": response,
                }
            )

            self.conversation_context = (
                self.conversation_context[-5:]
            )

            return response

        # =====================================================
        # EXECUTE PLAN
        # =====================================================

        results = []

        completed_steps = {}

        for step in plan:

            step_number = step.get(
                "step",
                len(results) + 1,
            )

            action = step.get(
                "action"
            )

            arguments = step.get(
                "arguments",
                {},
            )

            description = step.get(
                "description",
                action,
            )

            depends_on = step.get(
                "depends_on",
                [],
            )

            # -------------------------------------------------
            # DEPENDENCY CHECK
            # -------------------------------------------------

            if not self.dependencies_completed(
                step,
                completed_steps,
            ):

                print(
                    f"⛔ Agent step "
                    f"{step_number} skipped."
                )

                print(
                    f"   Depends on: "
                    f"{depends_on}"
                )

                dependency_result = {
                    "step": step_number,
                    "action": action,
                    "success": False,
                    "skipped": True,
                    "error": (
                        "Required previous "
                        "step failed or was "
                        "not completed."
                    ),
                    "depends_on": depends_on,
                }

                results.append(
                    dependency_result
                )

                completed_steps[
                    step_number
                ] = dependency_result

                break

            print(
                f"🧩 Agent step "
                f"{step_number}: "
                f"{description}"
            )

            if depends_on:

                print(
                    f"   ↳ Depends on: "
                    f"{depends_on}"
                )

            # -------------------------------------------------
            # CONVERSATION
            # -------------------------------------------------

            if action == "conversation":

                result = self.brain.process(
                    description
                )

                step_result = {
                    "step": step_number,
                    "action": action,
                    "success": True,
                    "result": result,
                    "depends_on": depends_on,
                }

                results.append(
                    step_result
                )

                completed_steps[
                    step_number
                ] = step_result

                print(
                    f"✅ Agent step "
                    f"{step_number} completed."
                )

                continue

            # -------------------------------------------------
            # GET TOOL
            # -------------------------------------------------

            tool = self.brain.tools.get(
                action
            )

            if not tool:

                error = (
                    f"Tool '{action}' "
                    "does not exist."
                )

                print(
                    f"❌ {error}"
                )

                step_result = {
                    "step": step_number,
                    "action": action,
                    "success": False,
                    "error": error,
                    "depends_on": depends_on,
                }

                results.append(
                    step_result
                )

                completed_steps[
                    step_number
                ] = step_result

                break

            # -------------------------------------------------
            # DEPENDENCY CONTEXT
            # -------------------------------------------------

            dependency_context = (
                self.build_dependency_context(
                    step,
                    completed_steps,
                )
            )

            if dependency_context:

                print(
                    "   ↳ Previous results "
                    "available."
                )

            # -------------------------------------------------
            # RESOLVE ARGUMENTS
            # -------------------------------------------------

            try:

                resolved_arguments = (
                    self.resolve_arguments(
                        arguments,
                        completed_steps,
                    )
                )

                if (
                    resolved_arguments
                    != arguments
                ):

                    print(
                        "   ↳ Dependency "
                        "values resolved."
                    )

            except Exception as e:

                result = {
                    "success": False,
                    "error": str(e),
                }

                step_result = {
                    "step": step_number,
                    "action": action,
                    **result,
                    "depends_on": depends_on,
                }

                results.append(
                    step_result
                )

                completed_steps[
                    step_number
                ] = step_result

                break

            # -------------------------------------------------
            # EXECUTE TOOL
            # -------------------------------------------------
            # -------------------------------------------------
            # DANGEROUS POWER ACTIONS
            # -------------------------------------------------
            #
            # These actions MUST NEVER execute directly.
            # Confirmation must happen before the real tool call.
            #
            # -------------------------------------------------

            if action in (
                "shutdown_pc",
                "restart_pc",
            ):

                confirmation_message = (
                    "Are you sure you want to "
                    f"{'shut down' if action == 'shutdown_pc' else 'restart'} "
                    "the PC? Please confirm with yes or no."
                )

                # IMPORTANT:
                # Never trust Gemini/planner's "confirmed" value.
                # First execution is ALWAYS unconfirmed.
                pending_arguments = (
                    resolved_arguments.copy()
                )

                pending_arguments["confirmed"] = True

                self.confirmation_manager.set_pending(
                    action=action,
                    arguments=pending_arguments,
                    message=confirmation_message,
                    original_request=user_input,
                )

                print(
                    "🔐 Confirmation required."
                )

                return confirmation_message
            try:

                result = (
                    self.brain.tools.execute(
                        action,
                        **resolved_arguments,
                    )
                )

            except Exception as e:

                result = {
                    "success": False,
                    "error": str(e),
                }

            # -------------------------------------------------
            # OBSERVE RESULT
            # -------------------------------------------------

            observation = self.observe_result(
                step,
                result,
            )

            if observation.get("success"):
                print(
                    f"👀 Agent observed: "
                    f"step {step_number} succeeded."
                )
            else:
                print(
                    f"👀 Agent observed: "
                    f"step {step_number} failed."
                )

                print(
                    f"   Reason: "
                    f"{observation.get('message')}"
                )

            # -------------------------------------------------
            # CHECK CONFIRMATION
            # -------------------------------------------------

            tool_result_data = result.get(
                "result",
                {}
            )

            if not isinstance(
                tool_result_data,
                dict,
            ):
                tool_result_data = {}

            confirmation_required = (
                result.get(
                    "requires_confirmation",
                    False,
                )
                or
                result.get(
                    "confirmation_required",
                    False,
                )
                or
                tool_result_data.get(
                    "requires_confirmation",
                    False,
                )
                or
                tool_result_data.get(
                    "confirmation_required",
                    False,
                )
            )

            if confirmation_required:

                confirmation_message = (
                    result.get(
                        "message",
                        "This action requires confirmation.",
                    )
                )

                pending_arguments = (
                    resolved_arguments.copy()
                )

                # -------------------------------------------------
                # POWER ACTIONS
                # -------------------------------------------------

                if action in (
                    "shutdown_pc",
                    "restart_pc",
                ):

                    # IMPORTANT:
                    # First execution only checks confirmation.
                    # Actual execution will happen with
                    # confirmed=True after user says YES.

                    pending_arguments["confirmed"] = True

                # -------------------------------------------------
                # CLOSE APPLICATION
                # -------------------------------------------------

                if action == "close_application":

                    pending_action = (
                        "force_close_application"
                    )

                    pending_arguments = {
                        "app_name":
                            pending_arguments.get(
                                "app_name",
                                pending_arguments.get(
                                    "application",
                                    "",
                                ),
                            )
                    }

                else:

                    pending_action = action

                self.confirmation_manager.set_pending(
                    action=pending_action,
                    arguments=pending_arguments,
                    message=confirmation_message,
                    original_request=user_input,
                )

                pending = (
                    self.confirmation_manager
                    .get_pending()
                )

                pending[
                    "original_request"
                ] = user_input

                print(
                    "🔐 Confirmation required."
                )

                step_result = {
                    "step": step_number,
                    "action": action,
                    "success": True,
                    "requires_confirmation": True,
                    "result": result,
                    "depends_on": depends_on,
                }

                results.append(
                    step_result
                )

                completed_steps[
                    step_number
                ] = step_result

                return confirmation_message
            
         
            # -------------------------------------------------
            # VERIFY RESULT
            # -------------------------------------------------

            verified = self.verify_result(
                step,
                result,
            )

            if verified:

                print(
                    f"🔎 Agent verified: "
                    f"step {step_number} completed successfully."
                )

            else:

                print(
                    f"🔎 Agent verification failed "
                    f"for step {step_number}."
                )

                failure = self.analyze_failure(
                    step,
                    result,
                )

                print(
                    f"   Failure analysis: "
                    f"{failure}"
                )

                # -------------------------------------------------
                # EXECUTE RECOVERY PLAN
                # -------------------------------------------------

                recovery = self.run_recovery(
                    user_input=user_input,
                    failed_step=failure,
                    completed_steps=completed_steps,
                    attempt=1,
                    max_attempts=2,
                )

                if recovery.get("success"):

                    print(
                        "🧠 Agent recovery plan is ready."
                    )

                    recovery_plan = recovery.get(
                        "plan"
                    )

                    print(
                        "🧩 Executing recovery plan..."
                    )

                    recovery_result = (
                        self.execute_recovery_plan_steps(
                            recovery_plan
                        )
                    )

                    if recovery_result.get(
                        "success"
                    ):

                        print(
                            "✅ Recovery plan "
                            "completed successfully."
                        )

                    else:

                        print(
                            "❌ Recovery plan "
                            "execution failed."
                        )

                        print(
                            f"   Reason: "
                            f"{recovery_result.get('error')}"
                        )
                else:

                    print(
                        "❌ Agent recovery failed."
                    )

                    print(
                        f"   Reason: "
                        f"{recovery.get('error')}"
                    )

            # -------------------------------------------------
            # NORMAL RESULT
            # -------------------------------------------------

            step_result = {
                "step": step_number,
                "action": action,
                **result,
                "depends_on": depends_on,
            }

            results.append(
                step_result
            )

            completed_steps[
                step_number
            ] = step_result

            if result.get(
                "success",
                False,
            ):

                print(
                    f"✅ Agent step "
                    f"{step_number} completed."
                )

            else:

                print(
                    f"❌ Agent step "
                    f"{step_number} failed:"
                )

                print(
                    result.get(
                        "error",
                        "Unknown error.",
                    )
                )

                break

        # =====================================================
        # NO RESULTS
        # =====================================================

        if not results:

            return (
                "I could not complete "
                "the requested task."
            )

        # =====================================================
        # FAILED STEPS
        # =====================================================

        failed_steps = [
            item
            for item in results
            if not item.get(
                "success",
                False,
            )
        ]

        if failed_steps:

            failed = failed_steps[-1]

            completed = len([
                item
                for item in results
                if item.get(
                    "success",
                    False,
                )
            ])

            if failed.get(
                "skipped",
                False,
            ):

                return (
                    f"I completed "
                    f"{completed} step(s), "
                    f"but step "
                    f"{failed.get('step')} "
                    "was skipped because "
                    "a required previous "
                    "step was not completed."
                )

            return (
                f"I completed "
                f"{completed} step(s), "
                f"but step "
                f"{failed.get('step')} "
                "failed: "
                f"{failed.get('error', 'Unknown error.')}"
            )

        # =====================================================
        # LOCAL RESPONSE
        # =====================================================

        local_response = (
            self.build_local_tool_response(
                user_input=user_input,
                results=results,
            )
        )

        if local_response:

            self.conversation_context.append(
                {
                    "user": user_input,
                    "tool_results": results,
                    "assistant": local_response,
                }
            )

            self.conversation_context = (
                self.conversation_context[-5:]
            )

            return local_response

        # =====================================================
        # GEMINI FINAL RESPONSE
        # =====================================================

        final_response = (
            self.brain.process_tool_results(
                user_input=user_input,
                tool_results=results,
            )
        )

        self.conversation_context.append(
            {
                "user": user_input,
                "tool_results": results,
                "assistant": final_response,
            }
        )

        self.conversation_context = (
            self.conversation_context[-5:]
        )

        return final_response

def execute(self, tool_name, **kwargs):

    tool = self.get(tool_name)

    if not tool:
        return {
            "success": False,
            "error": f"Tool '{tool_name}' does not exist.",
        }

    try:
        result = tool["function"](**kwargs)

        # Preserve the original registry structure,
        # but also preserve a tool's own success=False.
        if isinstance(result, dict) and "success" in result:

            if result.get("success") is False:
                return {
                    "success": False,
                    "error": result.get(
                        "error",
                        "Tool execution failed.",
                    ),
                    "result": result,
                }

        return {
            "success": True,
            "result": result,
        }

    except Exception as e:
        return {
            "success": False,
            "error": str(e),
        }

def execute(self, name, **kwargs):
        """
        Execute a registered tool while preserving
        the tool's own success/failure status.
        """

        tool = self.get(name)

        if tool is None:
            return {
                "success": False,
                "error": (
                    f"Tool '{name}' is not registered."
                ),
            }

        try:

            result = tool["function"](
                **kwargs
            )

            # -------------------------------------------------
            # Preserve structured tool results
            # -------------------------------------------------

            if isinstance(result, dict):

                if "success" in result:

                    return result

                return {
                    "success": True,
                    "result": result,
                }

            # -------------------------------------------------
            # Non-dict tool result
            # -------------------------------------------------

            return {
                "success": True,
                "result": result,
            }

        except Exception as e:

            return {
                "success": False,
                "error": str(e),
            }

